(256, 'sccss_settings', 'a:1:{s:13:\"sccss-content\";s:3580:\"/* Fondo de la barra de navegación */\r\n.wp-block-navigation,\r\n.wp-block-navigation__container,\r\nheader,\r\n.site-header {\r\n    background-color: #12375C !important;\r\n}\r\n\r\n/* Color de los enlaces */\r\n.wp-block-navigation a {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Color al pasar el mouse */\r\n.wp-block-navigation a:hover {\r\n    color: #FFD700 !important;\r\n}\r\n\r\n/* Elemento activo */\r\n.wp-block-navigation .current-menu-item a,\r\n.wp-block-navigation .current_page_item a {\r\n    color: #FFD700 !important;\r\n}\r\n\r\n/* Fondo de la barra de navegación */\r\n.wp-block-navigation,\r\n.wp-block-navigation__container,\r\nheader,\r\n.site-header {\r\n    background-color: #12375C !important;\r\n}\r\n\r\n/* Color de los enlaces */\r\n.wp-block-navigation a {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Color al pasar el mouse */\r\n.wp-block-navigation a:hover {\r\n    color: #FFD700 !important;\r\n}\r\n\r\n/* Elemento activo */\r\n.wp-block-navigation .current-menu-item a,\r\n.wp-block-navigation .current_page_item a {\r\n    color: #FFD700 !important;\r\n}\r\n\r\n/* Fondo del footer */\r\nfooter,\r\n.wp-block-template-part footer,\r\n.site-footer {\r\n    background-color: #12375C !important;\r\n}\r\n\r\n/* Texto del footer */\r\nfooter,\r\nfooter p,\r\nfooter span,\r\nfooter a,\r\nfooter li,\r\nfooter h1,\r\nfooter h2,\r\nfooter h3,\r\nfooter h4,\r\nfooter h5,\r\nfooter h6 {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Enlaces del footer */\r\nfooter a {\r\n    text-decoration: none;\r\n}\r\n\r\n/* Color al pasar el mouse */\r\nfooter a:hover {\r\n    color: #FFD700 !important;\r\n}\r\n\r\n/* Título del sitio */\r\n.wp-block-site-title a,\r\n.wp-block-site-title,\r\n.site-title a,\r\n.site-title {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Mantener blanco al pasar el mouse y al visitar */\r\n.wp-block-site-title a:hover,\r\n.wp-block-site-title a:visited,\r\n.site-title a:hover,\r\n.site-title a:visited {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Título principal de la página */\r\n.wp-block-post-title {\r\n    color: #12375C !important;\r\n}\r\n/* Enlaces del menú */\r\nheader a,\r\n.site-header a,\r\n.wp-block-navigation a {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Logo o título del sitio */\r\n.wp-block-site-title a,\r\n.site-title a {\r\n    color: #ffffff !important;\r\n}\r\n\r\n/* Color al pasar el mouse */\r\n.wp-block-navigation a:hover,\r\nheader a:hover {\r\n    color: #d6e8ff !important;\r\n}\r\n\r\n\r\n\r\n/* MENÚ RESPONSIVE - Servicios Médicos */\r\n.wp-block-navigation .wp-block-navigation__responsive-container {\r\n  background-color: #12375C !important;\r\n  color: #ffffff !important;\r\n}\r\n\r\n/* Botón hamburguesa y botón cerrar */\r\n.wp-block-navigation .wp-block-navigation__responsive-container-open,\r\n.wp-block-navigation .wp-block-navigation__responsive-container-close {\r\n  color: #ffffff !important;\r\n  background: transparent !important;\r\n  border: none !important;\r\n}\r\n\r\n/* Íconos SVG del menú */\r\n.wp-block-navigation .wp-block-navigation__responsive-container-open svg,\r\n.wp-block-navigation .wp-block-navigation__responsive-container-close svg {\r\n  fill: currentColor !important;\r\n}\r\n\r\n/* Links dentro del menú móvil */\r\n.wp-block-navigation .wp-block-navigation__responsive-container .wp-block-navigation-item__content {\r\n  color: #ffffff !important;\r\n}\r\n\r\n.wp-block-navigation .wp-block-navigation__responsive-container .wp-block-navigation-item__content:hover,\r\n.wp-block-navigation .wp-block-navigation__responsive-container .wp-block-navigation-item__content:focus {\r\n  color: #FFD700 !important;\r\n}\r\n\r\n/* Por si el tema agrega fondo extra al contenido */\r\n.wp-block-navigation .wp-block-navigation__responsive-container-content {\r\n  background-color: #12375C !important;\r\n}\r\n\";}', 'auto'),
