:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Participamos en programas de educación y concienciación sobre la salud, colaboramos con organizaciones locales y apoyamos iniciativas que promueven estilos de vida saludables. También invertimos en investigación y desarrollo junto a instituciones académicas.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#f8fafc\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#f8fafc\"><!-- wp:heading {\"style\":{\"color\":{\"background\":\"#f8fafc\",\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-color has-background has-link-color\" style=\"color:#12375c;background-color:#f8fafc\">Beneficios de trabajar con nosotros</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Desarrollo profesional:</strong> capacitación continua y apoyo para conferencias del área</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Equilibrio trabajo-vida personal:</strong> horarios flexibles y opciones de trabajo remoto.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ambiente colaborativo:</strong> trabajo en equipo con profesionales comprometidos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Compensación competitiva:</strong> salario justo, seguro médico y planes de jubilación.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tecnología de vanguardia:</strong> herramientas de última generación.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Cultura de apoyo:</strong> comunicación abierta y ambiente de trabajo positivo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#12375c\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"},\"blockGap\":\"var:preset|spacing|20\"}},\"layout\":{\"type\":\"constrained\",\"wideSize\":\"\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#12375c;margin-top:var(--wp--preset--spacing--80);margin-bottom:var(--wp--preset--spacing--80);padding-top:40px;padding-right:0;padding-bottom:40px;padding-left:0\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"textColor\":\"base\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-base-color has-text-color has-link-color\">¡Únete a nosotros!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"textColor\":\"base\"} -->\n<p class=\"has-text-align-center has-base-color has-text-color has-link-color\">Si compartes nuestra pasión por la atención médica de calidad, te invitamos a explorar las oportunidades disponibles</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textAlign\":\"center\",\"backgroundColor\":\"base\",\"width\":50,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}},\"color\":{\"text\":\"#12375c\"},\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":{\"topLeft\":\"100px\",\"topRight\":\"100px\",\"bottomLeft\":\"100px\",\"bottomRight\":\"100px\"}}}} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-50\"><a class=\"wp-block-button__link has-base-background-color has-text-color has-background has-link-color has-text-align-center wp-element-button\" href=\"http://localhost:8080/ServiciosMedicos2/PHPAut/lista-de-puestos-disponibles/\" style=\"border-style:none;border-width:0px;border-top-left-radius:100px;border-top-right-radius:100px;border-bottom-left-radius:100px;border-bottom-right-radius:100px;color:#12375c\"><strong>Ver puestos disponibles</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', '', '', 'publish', 'closed', 'closed', '', '36-2', '', '', '2026-07-26 01:04:44', '2026-07-26 01:04:44', '', 0, 'http://localhost:8080/ServiciosMedicos2/PHPAut/?page_id=36', 0, 'page', '', 0),
