(54, 1, '2026-07-26 01:03:36', '2026-07-26 01:03:36', '<!-- wp:group {\"style\":{\"position\":{\"type\":\"\"},\"spacing\":{\"padding\":{\"top\":\"100px\",\"bottom\":\"100px\",\"left\":\"40px\",\"right\":\"40px\"},\"margin\":{\"top\":\"50px\",\"bottom\":\"50px\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"wideSize\":\"\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:50px;margin-bottom:50px;padding-top:100px;padding-right:40px;padding-bottom:100px;padding-left:40px\"><!-- wp:heading {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}},\"color\":{\"text\":\"#12375c\"}}} -->\n<h2 class=\"wp-block-heading has-text-color has-link-color\" style=\"color:#12375c\">¿Quiénes somos?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":50,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8080/ServiciosMedicos2/PHPAut/wp-content/uploads/2026/07/ChatGPT-Image-19-jul-2026-18_26_54-1.png\" alt=\"\" class=\"wp-image-50\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>En Servicios Médicos S.A creemos que todos merecen acceso a la atención médica de calidad. Nuestra misión es ofrecer servicios médicos integrales y personalizados, promover la salud y el bienestar, y marcar una diferencia positiva en la vida de nuestros pacientes, apoyados en un equipo de profesionales altamente capacitados</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"100px\",\"bottom\":\"100px\",\"left\":\"40px\",\"right\":\"40px\"},\"margin\":{\"top\":\"50px\",\"bottom\":\"50px\"}},\"color\":{\"background\":\"#f8fafc\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#f8fafc;margin-top:50px;margin-bottom:50px;padding-top:100px;padding-right:40px;padding-bottom:100px;padding-left:40px\"><!-- wp:heading {\"style\":{\"color\":{\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-color has-link-color\" style=\"color:#12375c\">Nuestros valores fundamentales</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Cuidado centrado en el paciente:</strong> atención compasiva, respetuosa y personalizada.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Excelencia médica:</strong> los más altos estándares de precisión, seguridad y eficacia</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tecnología avanzada:</strong> equipos de última generación para diagnósticos efectivos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Confidencialidad y ética:</strong> respeto absoluto por la privacidad de nuestros pacientes.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"style\":{\"color\":{\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-color has-link-color\" style=\"color:#12375c\">¿Dónde nos ubicamos?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":49,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8080/ServiciosMedicos2/PHPAut/wp-content/uploads/2026/07/Mapa-de-Cartago-Costa-Rica-1.png\" alt=\"\" class=\"wp-image-49\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Cartago, Costa Rica. Instalaciones accesibles y modernas para brindar la mejor experiencia a pacientes y colaboradores.</p>\n<!-- /wp:paragraph -->', 'Bienvenido a Servicios Médicos S.A', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-07-26 01:03:36', '2026-07-26 01:03:36', '', 16, 'http://localhost:8080/ServiciosMedicos2/PHPAut/?p=54', 0, 'revision', '', 0),
(55, 1, '2026-07-26 01:04:14', '2026-07-26 01:04:14', '<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Atención médica integral respaldada por profesionales comprometidos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"100px\",\"bottom\":\"100px\",\"left\":\"40px\",\"right\":\"40px\"},\"margin\":{\"top\":\"50px\",\"bottom\":\"50px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:50px;margin-bottom:50px;padding-top:100px;padding-right:40px;padding-bottom:100px;padding-left:40px\"><!-- wp:heading {\"style\":{\"color\":{\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-color has-link-color\" style=\"color:#12375c\">Nuestros servicios</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":51,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8080/ServiciosMedicos2/PHPAut/wp-content/uploads/2026/07/Servicios-medicos-para-tu-bienestar-1.png\" alt=\"\" class=\"wp-image-51\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Consultas médicas y exámenes físicos completos</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Diagnóstico y tratamiento de enfermedades agudas y crónicas</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Atención preventiva y promoción de la salud</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Servicios de laboratorio y pruebas diagnósticas</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Servicios de imágenes médicas (radiografías, resonancias)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cirugías y procedimientos médicos especializados</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Nuestro equipo</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":53,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8080/ServiciosMedicos2/PHPAut/wp-content/uploads/2026/07/istockphoto-2218491828-612x612-2.jpg\" alt=\"\" class=\"wp-image-53\"/><figcaption class=\"wp-element-caption\">Portrait featuring a multi-ethnic medical team smiling confidently at the camera while gathered in a bustling hospital corridor</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Contamos con un equipo multidisciplinario de médicos, especialistas, enfermeras y personal de apoyo dedicados a brindar una atención integral y de calidad.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->', 'Nuestros Servicios y Equipo', '', 'inherit', 'closed', 'closed', '', '30-revision-v1', '', '', '2026-07-26 01:04:14', '2026-07-26 01:04:14', '', 30, 'http://localhost:8080/ServiciosMedicos2/PHPAut/?p=55', 0, 'revision', '', 0),
(56, 1, '2026-07-26 01:04:44', '2026-07-26 01:04:44', '<!-- wp:group {\"style\":{\"color\":{\"background\":\"#f8fafc\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#f8fafc;margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color has-link-color\" style=\"color:#12375c\">Comunidad y Carreras</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Construyendo una comunidad más saludable, juntos</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"100px\",\"bottom\":\"100px\",\"left\":\"40px\",\"right\":\"40px\"},\"margin\":{\"top\":\"50px\",\"bottom\":\"50px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:50px;margin-bottom:50px;padding-top:100px;padding-right:40px;padding-bottom:100px;padding-left:40px\"><!-- wp:heading {\"style\":{\"color\":{\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-color has-link-color\" style=\"color:#12375c\">Compromiso con la comunidad </h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":52,\"width\":\"631px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost:8080/ServiciosMedicos2/PHPAut/wp-content/uploads/2026/07/compromiso_comunidad-1.png\" alt=\"\" class=\"wp-image-52\" style=\"width:631px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Participamos en programas de educación y concienciación sobre la salud, colaboramos con organizaciones locales y apoyamos iniciativas que promueven estilos de vida saludables. También invertimos en investigación y desarrollo junto a instituciones académicas.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#f8fafc\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#f8fafc\"><!-- wp:heading {\"style\":{\"color\":{\"background\":\"#f8fafc\",\"text\":\"#12375c\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}}}} -->\n<h2 class=\"wp-block-heading has-text-color has-background has-link-color\" style=\"color:#12375c;background-color:#f8fafc\">Beneficios de trabajar con nosotros</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Desarrollo profesional:</strong> capacitación continua y apoyo para conferencias del área</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Equilibrio trabajo-vida personal:</strong> horarios flexibles y opciones de trabajo remoto.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Ambiente colaborativo:</strong> trabajo en equipo con profesionales comprometidos.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Compensación competitiva:</strong> salario justo, seguro médico y planes de jubilación.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tecnología de vanguardia:</strong> herramientas de última generación.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Cultura de apoyo:</strong> comunicación abierta y ambiente de trabajo positivo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#12375c\"},\"spacing\":{\"padding\":{\"top\":\"40px\",\"bottom\":\"40px\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"},\"blockGap\":\"var:preset|spacing|20\"}},\"layout\":{\"type\":\"constrained\",\"wideSize\":\"\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#12375c;margin-top:var(--wp--preset--spacing--80);margin-bottom:var(--wp--preset--spacing--80);padding-top:40px;padding-right:0;padding-bottom:40px;padding-left:0\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"textColor\":\"base\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-base-color has-text-color has-link-color\">¡Únete a nosotros!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"textColor\":\"base\"} -->\n<p class=\"has-text-align-center has-base-color has-text-color has-link-color\">Si compartes nuestra pasión por la atención médica de calidad, te invitamos a explorar las oportunidades disponibles</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textAlign\":\"center\",\"backgroundColor\":\"base\",\"width\":50,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#12375c\"}}},\"color\":{\"text\":\"#12375c\"},\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":{\"topLeft\":\"100px\",\"topRight\":\"100px\",\"bottomLeft\":\"100px\",\"bottomRight\":\"100px\"}}}} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-50\"><a class=\"wp-block-button__link has-base-background-color has-text-color has-background has-link-color has-text-align-center wp-element-button\" href=\"http://localhost:8080/ServiciosMedicos2/PHPAut/lista-de-puestos-disponibles/\" style=\"border-style:none;border-width:0px;border-top-left-radius:100px;border-top-right-radius:100px;border-bottom-left-radius:100px;border-bottom-right-radius:100px;color:#12375c\"><strong>Ver puestos disponibles</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', '', '', 'inherit', 'closed', 'closed', '', '36-revision-v1', '', '', '2026-07-26 01:04:44', '2026-07-26 01:04:44', '', 36, 'http://localhost:8080/ServiciosMedicos2/PHPAut/?p=56', 0, 'revision', '', 0),
